const body = $input.item.json.body ?? $input.item.json;

function normalizePhone(phone) {
  if (!phone) return null;
  let d = String(phone).replace(/\D/g, '');
  if (!d.startsWith('55')) d = '55' + d;
  if (d.length < 12) return null;
  return d; // sem o +
}

function calcValidUntil(paidAt) {
  const base  = paidAt ? new Date(paidAt) : new Date();
  const day   = base.getDate();
  const month = base.getMonth();
  const year  = base.getFullYear();

  const candidate = new Date(year, month + 1, day);

  const expectedMonth = (month + 1) % 12;
  if (candidate.getMonth() !== expectedMonth) {
    return new Date(year, month + 2, 0).toISOString().split('T')[0];
  }

  return candidate.toISOString().split('T')[0];
}

const eventTypeMap = {
  'Purchase_Order_Confirmed':  'purchase',
  'Recurrent_Payment':         'renewal',
  'Payment_Refund':            'refund',
  'Refund_Requested':          'refund_requested',
  'Payment_Chargeback':        'chargeback',
  'Subscription_Canceled':     'canceled',
  'Subscription_Expired':      'expired',
  'Purchase_Request_Canceled': 'canceled',
  'Purchase_Request_Expired':  'expired',
  'Abandoned_Cart':            'abandoned_cart',
  'Product_Access_Ended':      'access_ended'
};

const routeMap = {
  'purchase':         'compra',
  'renewal':          'renovacao',
  'canceled':         'cancelamento',
  'expired':          'expiracao',
  'refund':           'reembolso',
  'chargeback':       'reembolso',
  'refund_requested': 'outros',
  'abandoned_cart':   'carrinho_abandonado',
  'access_ended':     'access_ended'
};

const buyer    = body?.Data?.Buyer ?? {};
const purchase = body?.Data?.Purchase ?? {};
const subs     = body?.Data?.Subscriptions ?? [];
const offer    = body?.Data?.Offer ?? {};
const products = body?.Data?.Products ?? [];
const utm      = body?.Data?.Utm ?? {};
const mainProd = products.find(p => p.Price) ?? products[0] ?? {};
const sub      = subs[0] ?? {};
const normType = eventTypeMap[body.Event] ?? 'other';
const paidAt   = purchase.PaymentDate ?? null;

return {
  event_id:                body.Id,
  event_type:              body.Event,
  normalized_event_type:   normType,
  route:                   routeMap[normType] ?? 'outros',
  is_test:                 body.IsTest ?? false,
  gateway:                 'lastlink',
  raw_payload:             JSON.stringify(body),

  buyer_phone:             normalizePhone(buyer.PhoneNumber),
  buyer_email:             buyer.Email ? buyer.Email.toLowerCase().trim() : null,
  buyer_name:              buyer.Name ?? null,
  buyer_first_name:        buyer.Name ? buyer.Name.trim().split(' ')[0] : '',

  gateway_subscription_id: sub.Id ?? null,
  canceled_date:           sub.CanceledDate ?? null,
  cancellation_reason:     sub.CancellationReason ?? null,
  expired_date:            sub.ExpiredDate ?? null,

  valid_until_calculated:  (normType === 'purchase' || normType === 'renewal')
                             ? calcValidUntil(paidAt)
                             : null,

  access_ended_at:         body?.Data?.AccessEndedAt ?? null,

  offer_id:                offer.Id ?? null,
  offer_name:              offer.Name ?? null,
  offer_url:               offer.Url ?? null,
  product_id:              mainProd.Id ?? null,
  product_name:            mainProd.Name ?? null,

  gateway_payment_id:      purchase.PaymentId ?? null,
  amount:                  purchase.Price?.Value ?? null,
  original_amount:         purchase.OriginalPrice?.Value ?? null,
  payment_method:          purchase.Payment?.PaymentMethod === 'bankslip'
                             ? 'boleto'
                             : (purchase.Payment?.PaymentMethod ?? null),
  installments:            purchase.Payment?.NumberOfInstallments ?? 1,
  recurrency_number:       purchase.Recurrency ?? 1,
  paid_at:                 paidAt,
  chargeback_at:           purchase.ChargebackDate ?? null,

  utm_source:              utm.UtmSource ?? null,
  utm_medium:              utm.UtmMedium ?? null,
  utm_campaign:            utm.UtmCampaign ?? null,

  affiliate_id:            purchase.Affiliate?.Id ?? null,
  affiliate_email:         purchase.Affiliate?.Email ?? null
};
